Here is a comprehensive pytest suite covering happy paths, edge cases, and error cases.

```python
import pytest


# Replace this with the actual import from your module
# from my_module import zip_dicts

def zip_dicts(*dicts) -> dict:
    """Local copy for self-contained example."""
    keys = set().union(*dicts)
    return {k: [d.get(k) for d in dicts] for k in keys}


class TestZipDictsHappyPath:
    """Standard usage scenarios."""

    def test_two_dicts_same_keys(self):
        result = zip_dicts({"a": 1, "b": 2}, {"a": 3, "b": 4})
        assert result == {"a": [1, 3], "b": [2, 4]}

    def test_three_dicts_mixed_keys(self):
        result = zip_dicts(
            {"a": 1},
            {"a": 2, "b": 3},
            {"c": 4},
        )
        assert result == {
            "a": [1, 2, None],
            "b": [None, 3, None],
            "c": [None, None, 4],
        }

    def test_single_dict(self):
        result = zip_dicts({"x": 10, "y": 20})
        assert result == {"x": [10], "y": [20]}

    def test_values_are_references_not_copies(self):
        """Ensure mutable values inside input dicts are not deep-copied."""
        inner = [1, 2]
        result = zip_dicts({"a": inner}, {"a": [3, 4]})
        assert result["a"][0] is inner


class TestZipDictsEdgeCases:
    """Boundary conditions and unusual but valid inputs."""

    def test_no_arguments_returns_empty_dict(self):
        assert zip_dicts() == {}

    def test_single_empty_dict(self):
        assert zip_dicts({}) == {}

    def test_multiple_empty_dicts(self):
        assert zip_dicts({}, {}, {}) == {}

    def test_disjoint_keys(self):
        result = zip_dicts({"a": 1}, {"b": 2}, {"c": 3})
        assert result == {
            "a": [1, None, None],
            "b": [None, 2, None],
            "c": [None, None, 3],
        }

    def test_explicit_none_value_indistinguishable_from_missing(self):
        """
        zip_dicts uses dict.get(), so a key explicitly set to None looks
        identical to a missing key in the final list.
        """
        result = zip_dicts({"a": None}, {"a": 1})
        assert result == {"a": [None, 1]}

        result2 = zip_dicts({"a": 1}, {"b": None})
        # "a" is missing from the second dict -> None
        # "b" is missing from the first dict -> None, but explicitly None in second
        assert result2 == {"a": [1, None], "b": [None, None]}

    def test_dict_subclass(self):
        """Works with any dict-like object that supports iteration and .get()."""
        from collections import defaultdict

        d1 = defaultdict(int, {"a": 1})
        d2 = defaultdict(int, {"b": 2})
        result = zip_dicts(d1, d2)
        assert result == {"a": [1, None], "b": [None, 2]}


class TestZipDictsErrorCases:
    """Invalid inputs that should raise exceptions."""

    def test_non_dict_iterable_raises_attribute_error(self):
        """Lists are iterable but lack a .get() method."""
        with pytest.raises(AttributeError):
            zip_dicts([1, 2, 3])

    def test_non_iterable_raises_type_error(self):
        """set().union() fails before .get() is ever called."""
        with pytest.raises(TypeError):
            zip_dicts(42)

    def test_string_argument_raises_attribute_error(self):
        """Strings are iterable, so they pass set().union() but lack .get()."""
        with pytest.raises(AttributeError):
            zip_dicts("abc")

    def test_mixed_valid_and_invalid_raises_on_invalid(self):
        """Errors should surface as soon as the invalid argument is processed."""
        with pytest.raises(AttributeError):
            zip_dicts({"a": 1}, "invalid")

    def test_dict_followed_by_non_iterable(self):
        with pytest.raises(TypeError):
            zip_dicts({"a": 1}, None)
```

### Key coverage points

| Category | What is tested |
|----------|----------------|
| **Happy Path** | Same keys, mixed keys, single dict, reference semantics |
| **Edge Cases** | No args, empty dicts, disjoint keys, explicit `None` values vs. missing keys, dict subclasses |
| **Error Cases** | List (iterable, no `.get`), int (non-iterable), string (iterable, no `.get`), mixed valid/invalid inputs, `None` as an argument |

